// Illustrative only — generate bounded multiplicities, filter at the end.
public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> results = new ArrayList<>();
    enumerate(candidates, 0, target, new ArrayList<>(), results);
    return results;
}

private void enumerate(int[] c, int idx, int target, List<Integer> path, List<List<Integer>> results) {
    if (idx == c.length) {
        int sum = 0;
        for (int v : path) sum += v;
        if (sum == target) results.add(new ArrayList<>(path));
        return;
    }
    int maxCopies = target / c[idx];           // cap reuse for this candidate
    for (int k = 0; k <= maxCopies; k++) {     // try 0..maxCopies copies
        for (int t = 0; t < k; t++) path.add(c[idx]);
        enumerate(c, idx + 1, target, path, results);
        for (int t = 0; t < k; t++) path.remove(path.size() - 1);
    }
}

