public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> results = new ArrayList<>();
    Arrays.sort(candidates);                 // enables the early break prune
    backtrack(candidates, 0, target, new ArrayList<>(), results);
    return results;
}

private void backtrack(int[] candidates, int start, int remaining,
                       List<Integer> path, List<List<Integer>> results) {
    if (remaining == 0) {
        results.add(new ArrayList<>(path));  // store a COPY of the path
        return;
    }
    for (int i = start; i < candidates.length; i++) {
        if (candidates[i] > remaining) break;   // sorted → no later candidate fits
        path.add(candidates[i]);                // choose
        backtrack(candidates, i, remaining - candidates[i], path, results); // explore, i = reuse
        path.remove(path.size() - 1);           // un-choose
    }
}

